C. After the existing `describe('verifyWithJwks header.alg fallback', ...)` block (before `describe('verifyWithJwks security', ...)`), add a focused JWKS test. The existing test file already imports `verifyWithJwks`, `encodeBase64Url`, `utf8Encoder`, `signing`, `JwtHeaderInvalid`. Add:
```ts
describe('verifyWithJwks typ', () => {
  it('Should enforce the expected typ header', async () => {
    const payload = { message: 'hello world' }
    const kid = 'dummy'
    const keyPair = await crypto.subtle.generateKey(
      {
        name: 'RSASSA-PKCS1-v1_5',
        modulusLength: 2048,
        publicExponent: new Uint8Array([1, 0, 1]),
        hash: 'SHA-256',
      },
      true,
      ['sign', 'verify']
    )

    const header = { alg: 'RS256', typ: 'at+jwt', kid }
    const encode = (obj: object) => encodeBase64Url(utf8Encoder.encode(JSON.stringify(obj)).buffer)
    const encodedHeader = encode(header)
    const encodedPayload = encode(payload)
    const signingInput = `${encodedHeader}.${encodedPayload}`
    const signatureBuffer = await signing(
      keyPair.privateKey,
      'RS256',
      utf8Encoder.encode(signingInput)
    )
    const token = `${signingInput}.${encodeBase64Url(signatureBuffer)}`

    const jwk = await crypto.subtle.exportKey('jwk', keyPair.publicKey)
    const keys = [{ ...jwk, kid, use: 'sig', alg: 'RS256' }]

    await expect(verifyWithJwks(token, { keys, allowedAlgorithms: ['RS256'] })).rejects.toThrow(
      JwtHeaderInvalid
    )
    await expect(
      verifyWithJwks(token, {
        keys,
        allowedAlgorithms: ['RS256'],
        verification: { typ: 'at+jwt' },
      })
    ).resolves.toEqual(payload)
    await expect(
      verifyWithJwks(token, {
        keys,
        allowedAlgorithms: ['RS256'],
        verification: { typ: 'JWT' },
      })
    ).rejects.toThrow(JwtHeaderInvalid)
  })
})
```

